actions.script:
const loadRunner = ec.service.getLoadRunner() const serviceInfos = loadRunner.serviceInfos const serviceInfoList = [] for (let i = 0; i < serviceInfos.length; i++) { const serviceInfo = serviceInfos[i] const runsPerSecAvg = serviceInfo.totalTime ? serviceInfo.runCount / (serviceInfo.totalTime/1000) : 0 const timeSinceBegin = serviceInfo.lastRunTime - serviceInfo.beginTime const runsPerSecTime = timeSinceBegin ? serviceInfo.runCount / (timeSinceBegin/1000) : 0
const timeBinList = serviceInfo.timeBinList?.map(bin => { const stats = bin.artifactTypeStats const findCountTotal = stats.entityFindOneCount + stats.entityFindListCount + stats.entityFindIteratorCount + stats.entityFindCountCount const findTimeTotal = stats.entityFindOneTime + stats.entityFindListTime + stats.entityFindIteratorTime + stats.entityFindCountTime const cudCountTotal = stats.entityCreateCount + stats.entityUpdateCount + stats.entityDeleteCount const cudTimeTotal = stats.entityCreateTime + stats.entityUpdateTime + stats.entityDeleteTime return { runCount: bin.runCount, totalTime: bin.totalTime, timeAverage: (bin.runCount ? bin.totalTime / bin.runCount : 0), runsPerSecAvg: (bin.totalTime ? bin.runCount / (bin.totalTime/1000) : 0), entityFindsPerSec: (findTimeTotal ? findCountTotal / (findTimeTotal/1000000000) : 0), entityWritePerSec: (cudTimeTotal ? cudCountTotal / (cudTimeTotal/1000000000) : 0) } }) // remove the last time bin, is current and data can be weird until done if (timeBinList && timeBinList.length) timeBinList.pop()
serviceInfoList.push({serviceName: serviceInfo.serviceName, parametersExpr: serviceInfo.parametersExpr, targetThreads: serviceInfo.targetThreads, currentThreads: serviceInfo.currentThreads.get(), runDelayMs: serviceInfo.runDelayMs, rampDelayMs: serviceInfo.rampDelayMs, timeBinLength: serviceInfo.timeBinLength, timeBinsKeep: serviceInfo.timeBinsKeep, runCount: serviceInfo.runCount, errorCount: serviceInfo.errorCount, lastResult: serviceInfo.lastResult, beginTime: serviceInfo.beginTime, lastRunTime: serviceInfo.lastRunTime, lastRunTimeStr: new Date(serviceInfo.lastRunTime).toISOString(), totalTime: serviceInfo.totalTime, totalSquaredTime: serviceInfo.totalSquaredTime, minTime: serviceInfo.minTime, maxTime: serviceInfo.maxTime, timeAverage: (serviceInfo.runCount ? serviceInfo.totalTime / serviceInfo.runCount : 0), timeStdDev: (serviceInfo.totalSquaredTime && serviceInfo.runCount > 1 ? Math.sqrt(Math.abs(serviceInfo.totalSquaredTime - ((serviceInfo.totalTime*serviceInfo.totalTime) / serviceInfo.runCount)) / (serviceInfo.runCount - 1)) : null), runsPerSecAvg: runsPerSecAvg, runsPerSecTime: runsPerSecTime, busyPercent: (runsPerSecAvg ? 100*runsPerSecTime/runsPerSecAvg : 0), typeStats: ObjectUtilities.objectToMap(serviceInfo.artifactTypeStats), timeBinList: timeBinList }) }
const executor = loadRunner.scheduledExecutor const executorInfo = {execIndex: loadRunner.execIndex.get(), totalThreads: executor?.getQueue()?.size(), activeThreads: executor?.getActiveCount(), executorExists: !!executor, running: !!executor && !executor.shutdown && !executor.terminated && !executor.terminating, shutdown: executor?.shutdown, terminated: executor?.terminated, terminating: executor?.terminating}
const runnerInfo = {executorInfo: executorInfo, serviceInfos: serviceInfoList} ec.web.sendJsonResponse(runnerInfo)

render-mode.text:
${JSON.stringify((() => { try {
            if (typeof ec.service.getLoadRunner !== 'function')
                return [{t: 'text', id: 'LoadRunnerMissing', style: 'strong', text: 'The service load runner (ec.service.getLoadRunner) is not in this server.'}]
            const loadRunner = ec.service.getLoadRunner()
            const fmt = (value) => value == null ? '' : String(ec.l10n.format(value, '#,##0.##'))
            const safeDivide = (over, under) => under ? fmt(over / under) : '0'
            const serviceInfos = loadRunner.serviceInfos || []
            const first = serviceInfos.length ? serviceInfos[0] : null
            const parameters = (ec.web && ec.web.parameters) || {}
            const value = (name, fallback) => String(parameters[name] || (first && first[name] != null ? first[name] : '') || fallback)
            const executor = loadRunner.scheduledExecutor
            const executorExists = !!executor
            const running = !!executor && !executor.shutdown && !executor.terminated && !executor.terminating
            const thisUrl = sri.buildUrl('ServiceLoadRunner').url
            const populate = {serviceName: 'mantle.GeneralServices.lookup#ById', parametersExpr: "[lookupId:'100000']", targetThreads: '100',
                runDelayMs: '100', runDelayVaryMs: '10', rampDelayMs: '255', timeBinLength: '1000', timeBinsKeep: '60'}
            const populateUrl = thisUrl + '?' + Object.keys(populate).map((key) => key + '=' + encodeURIComponent(populate[key])).join('&')
            const field = (name, title, fallback) => ({t: 'field', id: 'LoadRunner_' + name, name: name, title: title,
                w: {kind: 'textLine', value: value(name, fallback)}})
            const nodes = [
                {t: 'link', id: 'LoadRunnerPopulate', text: 'Populate Test 1: Lookup By ID', url: populateUrl, kind: 'anchor', btnType: 'info'},
                {t: 'text', id: 'LoadRunnerUnits', style: 'strong', text: 'All delay, run, etc times are in milliseconds (ms), rates in runs per second'},
                {t: 'form', id: 'LoadRunnerServiceInfo', name: 'LoadRunnerServiceInfo', transitionUrl: sri.buildUrl('setServiceInfo').url, method: 'post',
                    hidden: [{name: 'runDelayVaryMs', value: value('runDelayVaryMs', '5')}],
                    c: [field('serviceName', 'Service Name', ''), field('parametersExpr', 'Parameters Expression', ''),
                        field('targetThreads', 'Threads', '10'), field('runDelayMs', 'Run Delay', '100'), field('rampDelayMs', 'Ramp Delay', '505'),
                        field('timeBinLength', 'Bin Length', '2000'), field('timeBinsKeep', 'Bins Keep', '20'),
                        {t: 'field', id: 'LoadRunner_submitBtn', name: 'submitBtn', title: 'Set Service Info', w: {kind: 'submit', text: 'Set Service Info'}}]},
                {t: 'link', id: 'LoadRunnerBegin', text: 'Begin', url: sri.buildUrl('begin').url, kind: 'hidden-form-link', method: 'post',
                    btnType: 'success', disabled: executorExists},
                {t: 'link', id: 'LoadRunnerStopWait', text: 'Stop Wait', url: sri.buildUrl('stopWait').url, kind: 'hidden-form-link', method: 'post',
                    btnType: 'danger', disabled: !running},
                {t: 'link', id: 'LoadRunnerRefresh', text: 'Refresh', url: thisUrl, kind: 'anchor'}]

            const statusParts = ['Exec Index ' + loadRunner.execIndex.get(), 'Total Threads ' + fmt(executor ? executor.getQueue().size() : null),
                'Active Threads ' + fmt(executor ? executor.getActiveCount() : null), 'Running ' + running]
            const serverStatus = ec.factory.getStatusMap(true) || {}
            if (serverStatus.System) statusParts.push('CPU Load ' + serverStatus.System.Load + ' (avg last minute)',
                serverStatus.System.CPU + ' ' + serverStatus.System.Processors + ' threads')
            if (serverStatus.Heap) statusParts.push('Heap RAM ' + serverStatus.Heap.Used + '/' + serverStatus.Heap.Committed + '/' + serverStatus.Heap.Max)
            if (serverStatus.JavaStats) statusParts.push('Java GC ' + serverStatus.JavaStats.GcCount + ' GCs ' + serverStatus.JavaStats.GcTimeSeconds + 's')
            nodes.push({t: 'text', id: 'LoadRunnerStatus', text: statusParts.join(' · ')})

            const rows = serviceInfos.map((info, index) => {
                const runsPerSecAvg = info.totalTime ? info.runCount / (info.totalTime / 1000) : 0
                const sinceBegin = info.lastRunTime - info.beginTime
                const runsPerSecTime = sinceBegin ? info.runCount / (sinceBegin / 1000) : 0
                const stdDev = info.totalSquaredTime && info.runCount > 1 ? Math.sqrt(Math.abs(info.totalSquaredTime -
                    ((info.totalTime * info.totalTime) / info.runCount)) / (info.runCount - 1)) : null
                return {id: String(index), cells: [[String(info.serviceName), String(info.parametersExpr || '')],
                    String(ec.l10n.format(info.beginTime, 'HH:mm:ss')) + ' - ' + fmt((Date.now() - info.beginTime) / 1000) + 's',
                    fmt(info.targetThreads), fmt(info.currentThreads.get()), fmt(info.runDelayMs), fmt(info.rampDelayMs), fmt(info.timeBinLength),
                    fmt(info.timeBinsKeep), fmt(info.runCount), fmt(info.errorCount), safeDivide(info.totalTime, info.runCount), fmt(stdDev),
                    fmt(info.minTime), fmt(info.maxTime), fmt(runsPerSecAvg), fmt(runsPerSecTime), runsPerSecAvg ? fmt(100 * runsPerSecTime / runsPerSecAvg) : '0',
                    info.lastRunTime ? new Date(info.lastRunTime).toISOString() : '']}
            })
            const right = (title) => ({title: title, align: 'right'})
            nodes.push({t: 'formList', id: 'LoadRunnerServices', name: 'LoadRunnerServices',
                columns: [{title: 'Service & Parameters'}, {title: 'Began'}, right('Target'), right('Current'), right('Run Delay'), right('Ramp Delay'),
                    right('Bin Length'), right('Bins Keep'), right('Run Count'), right('Error Count'), right('Time Average'), right('Std Dev'),
                    right('Min'), right('Max'), right('Runs/Sec Avg'), right('Runs/Sec Time'), right('Busy Pct'), {title: 'Last Run'}],
                rows: rows, paging: {index: 0, size: rows.length, count: rows.length}})

            const kinds = [['entityFindOne', 'Entity One'], ['entityFindList', 'Entity List'], ['entityFindIterator', 'Entity Iterator'],
                ['entityFindCount', 'Entity Count'], ['entityCreate', 'Entity Create'], ['entityUpdate', 'Entity Update'],
                ['entityDelete', 'Entity Delete'], ['serviceView', 'Service View'], ['serviceOther', 'Service Other']]
            const statRows = []
            serviceInfos.forEach((info, index) => {
                const stats = info.artifactTypeStats ? (typeof ObjectUtilities !== 'undefined' ? ObjectUtilities.objectToMap(info.artifactTypeStats)
                    : info.artifactTypeStats) : null
                if (!stats) return
                statRows.push({id: String(index), cells: [[String(info.serviceName), String(info.parametersExpr || '')], ['Runs', 'Average Time µs', 'Runs/Second']]
                    .concat(kinds.map(([kind]) => [fmt(stats[kind + 'Count']), safeDivide(stats[kind + 'Time'] / 1000, stats[kind + 'Count']),
                        safeDivide(stats[kind + 'Count'], stats[kind + 'Time'] / 1000000000)]))})
            })
            nodes.push({t: 'formList', id: 'LoadRunnerStats', name: 'LoadRunnerStats',
                columns: [{title: 'Service & Parameters'}, {title: ''}].concat(kinds.map(([, title]) => right(title))),
                rows: statRows, paging: {index: 0, size: statRows.length, count: statRows.length}})

            const bins = (info) => {
                const list = (info.timeBinList || []).map((bin) => {
                    const stats = bin.artifactTypeStats
                    const findCount = stats.entityFindOneCount + stats.entityFindListCount + stats.entityFindIteratorCount + stats.entityFindCountCount
                    const findTime = stats.entityFindOneTime + stats.entityFindListTime + stats.entityFindIteratorTime + stats.entityFindCountTime
                    const cudCount = stats.entityCreateCount + stats.entityUpdateCount + stats.entityDeleteCount
                    const cudTime = stats.entityCreateTime + stats.entityUpdateTime + stats.entityDeleteTime
                    return {beginTime: bin.beginTime, timeAverage: bin.runCount ? bin.totalTime / bin.runCount : 0,
                        runsPerSecAvg: bin.totalTime ? bin.runCount / (bin.totalTime / 1000) : 0,
                        entityFindsPerSec: findTime ? findCount / (findTime / 1000000000) : 0,
                        entityWritePerSec: cudTime ? cudCount / (cudTime / 1000000000) : 0}
                })
                if (list.length) list.pop()
                return list
            }
            const binLists = serviceInfos.map(bins)
            if (binLists.length && binLists[0].length) {
                const labels = binLists[0].map((bin) => bin.beginTime ? String(ec.l10n.format(bin.beginTime, 'HH:mm:ss')) : '')
                const chart = (id, title, name) => ({t: 'component', id: id, name: 'chart', props: {title: title, labels: labels,
                    series: serviceInfos.map((info, index) => ({name: String(info.serviceName), data: binLists[index].map((bin) => Math.round(bin[name] * 100) / 100)}))}})
                nodes.push(chart('LoadRunnerTimeChart', 'Average Run Time', 'timeAverage'), chart('LoadRunnerRunsChart', 'Runs per Second', 'runsPerSecAvg'),
                    chart('LoadRunnerFindsChart', 'Entity Finds per Second', 'entityFindsPerSec'),
                    chart('LoadRunnerWritesChart', 'Entity Writes per Second', 'entityWritePerSec'))
            }
            serviceInfos.forEach((info, index) => nodes.push({t: 'text', id: 'LoadRunnerLastResult' + index, style: 'pre',
                text: JSON.stringify(info.lastResult, null, 2) || ''}))
            return nodes
        } catch (err) {
            return [{t: 'text', id: 'LoadRunnerError', style: 'strong', text: 'The load runner cannot be read: ' + err}]
        } })())}
